     '다음 (1)과 (2)의 실무 물음에 답하시오.\n(1) CentOS 서버의 eth0 인터페이스에서 무차별 모드(PROMISC) 활성화가 확인되었다. ① 예상되는 공격명 ② 해제 명령어(ifconfig eth0 _____) ③ 해당 상태 진입 시점을 추적할 수 있는 리눅스 시스템 로그 경로를 쓰시오.\n(2) iptables의 -j 타깃 옵션 중 DROP과 REJECT의 차이를 설명하고, 보안 관점에서 더 권장되는 옵션과 이유를 서술하시오.',
