     '(1) ① 스니핑(Sniffing) 공격 ② ifconfig eth0 -promisc (iproute2: ip link set eth0 promisc off) ③ /var/log/messages\n(2) DROP은 패킷을 조용히 폐기하고 아무 응답도 보내지 않는 반면, REJECT는 TCP RST나 ICMP Destination Unreachable 오류 패킷을 송신자에게 회신한다. 보안 관점에서는 공격자에게 포트 존재·방화벽 동작 여부나 OS 정보를 노출하지 않고 리소스 소모를 줄이는 DROP이 권장된다.',
